async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') return handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') return handleListSessions(ws, session, sessionStore, message);
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const sessions = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {
      type: 'session_list',
      sessions: sessions.map(s => ({
        ...s,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
      })),
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    log.error('ws', 'listFor failed', {error: errorMessage, userId: session.userId});
    throw error;
  }
}

